GENERAL_KNOWLEDGE_EN = "General AI knowledge — not taken from your environment."


@dataclass(frozen=True)
class Method:
    id: str                 # tam kimlik veya 'önek*' deseni
    cls: str
    area: str               # sayfa gruplaması (capacity, reclaim, ...)
    method_tr: str
    method_en: str
    source_tr: str
    source_en: str
    limits_tr: str
    limits_en: str
    uses_ai: bool = False
    formula_tr: str = ""    # açılır teknik detay
    formula_en: str = ""


def _m(id: str, cls: str, area: str, method: Tuple[str, str], source: Tuple[str, str],
       limits: Tuple[str, str], ai: bool = False, formula: Tuple[str, str] = ("", "")) -> Method:
    assert cls in CLASSES, f"bilinmeyen yöntem sınıfı: {cls}"
    return Method(id, cls, area, method[0], method[1], source[0], source[1], limits[0], limits[1],
                  ai or cls == CLASS_AI, formula[0], formula[1])


